-- Add labeler-facing definitions and examples without changing the original V1/V2 migrations.
ALTER TABLE dimension_def ADD COLUMN IF NOT EXISTS definition TEXT;
ALTER TABLE dimension_def ADD COLUMN IF NOT EXISTS positive_example TEXT;
ALTER TABLE dimension_def ADD COLUMN IF NOT EXISTS negative_example TEXT;
ALTER TABLE dimension_def ADD COLUMN IF NOT EXISTS boundary_note TEXT;

ALTER TABLE attribute_def ADD COLUMN IF NOT EXISTS meaning TEXT;
ALTER TABLE attribute_def ADD COLUMN IF NOT EXISTS positive_example TEXT;
ALTER TABLE attribute_def ADD COLUMN IF NOT EXISTS negative_example TEXT;

UPDATE dimension_def SET definition=$cgdi$Internal processes the registrant uses to identify, assess, prevent, detect, respond to, recover from, remediate, or test cybersecurity risk.$cgdi$, positive_example=$cgdi$We conduct periodic cyber-risk assessments, monitor network activity, maintain an incident-response plan, train employees annually, and conduct tabletop and penetration-testing exercises.$cgdi$, negative_example=$cgdi$Cyberattacks are becoming more frequent and sophisticated and could materially harm our business.$cgdi$, boundary_note=$cgdi$A1 is the cyber-risk process itself. Do not code A2 unless the paragraph explicitly links cyber risk to broader ERM or enterprise decision processes.$cgdi$ WHERE code='A1';
UPDATE dimension_def SET definition=$cgdi$Explicit integration of cybersecurity into broader enterprise risk management, enterprise prioritization, strategy, or business decision processes.$cgdi$, positive_example=$cgdi$Cybersecurity risks are incorporated into our enterprise risk management framework; the Enterprise Risk Committee evaluates them alongside other principal risks and uses the assessment in strategic planning.$cgdi$, negative_example=$cgdi$Management performs cybersecurity risk assessments, and the Company also maintains an enterprise risk management program.$cgdi$, boundary_note=$cgdi$Separate references to cybersecurity and ERM are not enough. The paragraph must make the integration or enterprise-level decision link explicit.$cgdi$ WHERE code='A2';
UPDATE dimension_def SET definition=$cgdi$Processes used by the registrant to govern cybersecurity risk arising from vendors, suppliers, contractors, cloud providers, and other third parties.$cgdi$, positive_example=$cgdi$High-risk vendors complete security assessments, accept contractual security requirements, are reassessed annually, and unresolved findings are escalated for remediation.$cgdi$, negative_example=$cgdi$We rely on third-party cloud providers, and a breach at a provider could adversely affect us.$cgdi$, boundary_note=$cgdi$Third-party dependence or exposure alone is not governance. Look for assessment, tiering, contractual controls, monitoring, remediation, or escalation.$cgdi$ WHERE code='A3';
UPDATE dimension_def SET definition=$cgdi$The board-level body responsible for cybersecurity oversight and how that oversight responsibility is organized and exercised.$cgdi$, positive_example=$cgdi$The Board delegates cybersecurity oversight to the Audit Committee, which reviews the cyber-risk program, significant incidents, testing results, and remediation progress quarterly.$cgdi$, negative_example=$cgdi$The CISO manages the cybersecurity program.$cgdi$, boundary_note=$cgdi$B1 is board or board-committee oversight. Management responsibility belongs in B2; information moving to the board may also support C1.$cgdi$ WHERE code='B1';
UPDATE dimension_def SET definition=$cgdi$Responsible management roles, their cybersecurity responsibilities, reporting relationships, cross-functional coordination, and relevant expertise or qualifications.$cgdi$, positive_example=$cgdi$The CISO leads the cybersecurity program, reports to the Chief Risk Officer, coordinates incident response with Legal, Compliance, and IT, and has 20 years of security experience.$cgdi$, negative_example=$cgdi$Our executives recognize cybersecurity as an important risk.$cgdi$, boundary_note=$cgdi$B2 describes management responsibility and organization. Routine or event-triggered information transfer through governance channels belongs in C1.$cgdi$ WHERE code='B2';
UPDATE dimension_def SET definition=$cgdi$How cybersecurity information moves through governance channels, including routine reporting and event-triggered escalation.$cgdi$, positive_example=$cgdi$The CISO reports quarterly to the Audit Committee on threats, incidents, remediation status, and program metrics; significant incidents are escalated when severity thresholds are met.$cgdi$, negative_example=$cgdi$The Audit Committee oversees cybersecurity.$cgdi$, boundary_note=$cgdi$Oversight alone is B1. C1 requires an observable information flow: reporter, recipient, cadence/content, trigger, threshold, or escalation path.$cgdi$ WHERE code='C1';

UPDATE attribute_def SET meaning=$cgdi$Cyber-risk identification, assessment, evaluation, prioritization, vulnerability assessment, or threat analysis.$cgdi$, positive_example=$cgdi$We perform annual cybersecurity risk and vulnerability assessments.$cgdi$, negative_example=$cgdi$Cyber threats could materially affect us.$cgdi$ WHERE code='A1_risk_assessment';
UPDATE attribute_def SET meaning=$cgdi$Preventive or protective safeguards such as access controls, encryption, security controls, or protective architecture.$cgdi$, positive_example=$cgdi$We use multi-factor authentication and encryption to protect sensitive systems.$cgdi$, negative_example=$cgdi$We maintain secure systems.$cgdi$ WHERE code='A1_protective_controls';
UPDATE attribute_def SET meaning=$cgdi$Monitoring or detection activity such as security alerts, threat detection, network monitoring, or SOC activity.$cgdi$, positive_example=$cgdi$Our security operations center continuously monitors network activity for anomalies.$cgdi$, negative_example=$cgdi$We are aware of evolving cyber threats.$cgdi$ WHERE code='A1_monitoring_detection';
UPDATE attribute_def SET meaning=$cgdi$An incident-response plan or process, including investigation, containment, or response procedures.$cgdi$, positive_example=$cgdi$We maintain and periodically update an incident-response plan for cybersecurity events.$cgdi$, negative_example=$cgdi$Cyber incidents may occur.$cgdi$ WHERE code='A1_incident_response';
UPDATE attribute_def SET meaning=$cgdi$Cybersecurity training or awareness exercises for employees or executives.$cgdi$, positive_example=$cgdi$Employees complete annual cybersecurity and phishing-awareness training.$cgdi$, negative_example=$cgdi$Employees receive general compliance training.$cgdi$ WHERE code='A1_training_awareness';
UPDATE attribute_def SET meaning=$cgdi$Cyber-related recovery, restoration, remediation, business continuity, or resilience processes.$cgdi$, positive_example=$cgdi$Our cyber recovery procedures include restoration from backups and continuity planning after an attack.$cgdi$, negative_example=$cgdi$We maintain a general disaster-recovery plan with no cyber connection.$cgdi$ WHERE code='A1_recovery_resilience';
UPDATE attribute_def SET meaning=$cgdi$Testing or assurance of the cyber program, such as penetration tests, tabletop exercises, audits, red-team exercises, or control testing.$cgdi$, positive_example=$cgdi$We conduct annual penetration testing and tabletop exercises.$cgdi$, negative_example=$cgdi$We operate access controls.$cgdi$ WHERE code='A1_testing_assurance';
UPDATE attribute_def SET meaning=$cgdi$A direct statement that cybersecurity is integrated into, part of, or incorporated within enterprise risk management.$cgdi$, positive_example=$cgdi$Cybersecurity risk is incorporated into our enterprise risk management framework.$cgdi$, negative_example=$cgdi$We maintain both a cybersecurity program and an ERM program.$cgdi$ WHERE code='A2_explicit_erm_link';
UPDATE attribute_def SET meaning=$cgdi$An enterprise-risk function, risk committee, risk council, or other ERM actor that handles cybersecurity risk.$cgdi$, positive_example=$cgdi$The Enterprise Risk Committee reviews cybersecurity risk as part of ERM.$cgdi$, negative_example=$cgdi$The security team reviews cybersecurity risk.$cgdi$ WHERE code='A2_erm_actor';
UPDATE attribute_def SET meaning=$cgdi$Cyber risk is ranked, prioritized, or evaluated alongside other enterprise risks.$cgdi$, positive_example=$cgdi$Cyber risk is evaluated and prioritized alongside financial, operational, and strategic risks.$cgdi$, negative_example=$cgdi$The security team prioritizes cyber vulnerabilities.$cgdi$ WHERE code='A2_integration_prioritization';
UPDATE attribute_def SET meaning=$cgdi$Cyber-risk information explicitly informs strategy, capital allocation, enterprise objectives, or major business decisions.$cgdi$, positive_example=$cgdi$Cyber-risk assessments inform strategic planning and capital-allocation decisions.$cgdi$, negative_example=$cgdi$Cyber risk may affect our strategy.$cgdi$ WHERE code='A2_decision_strategy_link';
UPDATE attribute_def SET meaning=$cgdi$Cyber due diligence, questionnaires, audits, or security review of vendors, including onboarding assessments.$cgdi$, positive_example=$cgdi$High-risk vendors undergo cybersecurity due diligence before onboarding.$cgdi$, negative_example=$cgdi$We use third-party service providers.$cgdi$ WHERE code='A3_vendor_assessment';
UPDATE attribute_def SET meaning=$cgdi$Risk-based scope, tiering, classification, or focus on critical/high-risk vendors.$cgdi$, positive_example=$cgdi$Vendors are classified into risk tiers, with enhanced review for critical providers.$cgdi$, negative_example=$cgdi$All vendors complete the same basic procurement form.$cgdi$ WHERE code='A3_risk_scope_tiering';
UPDATE attribute_def SET meaning=$cgdi$Cybersecurity clauses or requirements in contracts, such as security standards, breach notice, or audit rights.$cgdi$, positive_example=$cgdi$Vendor contracts require security controls and prompt breach notification.$cgdi$, negative_example=$cgdi$Vendor contracts contain standard commercial terms.$cgdi$ WHERE code='A3_contractual_requirements';
UPDATE attribute_def SET meaning=$cgdi$Ongoing monitoring or periodic reassessment of third-party cyber risk.$cgdi$, positive_example=$cgdi$Critical vendors are reassessed annually and monitored for security changes.$cgdi$, negative_example=$cgdi$A vendor is reviewed once at onboarding.$cgdi$ WHERE code='A3_monitoring_reassessment';
UPDATE attribute_def SET meaning=$cgdi$Required remediation or escalation when third-party cyber issues remain unresolved, including suspension or termination.$cgdi$, positive_example=$cgdi$Unresolved vendor security findings are escalated and must be remediated before renewal.$cgdi$, negative_example=$cgdi$Vendors may expose us to cyber risk.$cgdi$ WHERE code='A3_remediation_escalation';
UPDATE attribute_def SET meaning=$cgdi$The Board or a named board committee has cybersecurity responsibility, including delegation from the Board.$cgdi$, positive_example=$cgdi$The Board delegates cybersecurity oversight to the Audit Committee.$cgdi$, negative_example=$cgdi$A management risk committee oversees cybersecurity.$cgdi$ WHERE code='B1_responsible_body_delegation';
UPDATE attribute_def SET meaning=$cgdi$An explicit board or board-committee mandate to oversee cybersecurity.$cgdi$, positive_example=$cgdi$The Audit Committee is responsible for oversight of cybersecurity risk.$cgdi$, negative_example=$cgdi$The Board received notice of one cyber incident.$cgdi$ WHERE code='B1_oversight_mandate';
UPDATE attribute_def SET meaning=$cgdi$The cybersecurity topics the Board or committee reviews, such as risks, incidents, controls, preparedness, testing, or remediation.$cgdi$, positive_example=$cgdi$The Audit Committee reviews cyber risks, incidents, testing results, and remediation progress.$cgdi$, negative_example=$cgdi$The Board discusses cybersecurity matters.$cgdi$ WHERE code='B1_review_scope';
UPDATE attribute_def SET meaning=$cgdi$An explicit cadence for board or committee cyber review, such as quarterly, annually, periodically, or at each meeting.$cgdi$, positive_example=$cgdi$The Audit Committee receives a cybersecurity review quarterly.$cgdi$, negative_example=$cgdi$The Board discusses cybersecurity from time to time.$cgdi$ WHERE code='B1_review_frequency';
UPDATE attribute_def SET meaning=$cgdi$An identifiable management role or committee responsible for cybersecurity, such as CISO, CIO, CTO, or risk officer.$cgdi$, positive_example=$cgdi$The CISO is responsible for the cybersecurity program.$cgdi$, negative_example=$cgdi$Management considers cybersecurity important.$cgdi$ WHERE code='B2_responsible_role';
UPDATE attribute_def SET meaning=$cgdi$The specific cyber responsibilities of a management role, such as program management, risk assessment, incident response, policy, or controls.$cgdi$, positive_example=$cgdi$The CISO is responsible for cyber risk assessment, security controls, and incident response.$cgdi$, negative_example=$cgdi$The company has a CISO.$cgdi$ WHERE code='B2_responsibility_scope';
UPDATE attribute_def SET meaning=$cgdi$The management reporting line of the responsible cybersecurity role.$cgdi$, positive_example=$cgdi$The CISO reports to the Chief Risk Officer.$cgdi$, negative_example=$cgdi$The CISO reports cybersecurity matters to the Board quarterly.$cgdi$ WHERE code='B2_reporting_line';
UPDATE attribute_def SET meaning=$cgdi$Explicit coordination among functions such as IT, Legal, Risk, Compliance, Finance, Operations, or a disclosure committee.$cgdi$, positive_example=$cgdi$The CISO coordinates incident response with Legal, Compliance, and IT.$cgdi$, negative_example=$cgdi$Legal, IT, and Compliance are each involved in cybersecurity.$cgdi$ WHERE code='B2_cross_functional_coordination';
UPDATE attribute_def SET meaning=$cgdi$Relevant cybersecurity experience, prior roles, certifications, education, or qualifications of a responsible management actor.$cgdi$, positive_example=$cgdi$The CISO has 20 years of information-security experience and holds a CISSP certification.$cgdi$, negative_example=$cgdi$The CISO is highly experienced.$cgdi$ WHERE code='B2_expertise_qualification';
UPDATE attribute_def SET meaning=$cgdi$The person or body that regularly provides cybersecurity information through a governance channel.$cgdi$, positive_example=$cgdi$The CISO reports cybersecurity information to the Audit Committee each quarter.$cgdi$, negative_example=$cgdi$The CISO is responsible for cybersecurity.$cgdi$ WHERE code='C1_routine_reporter';
UPDATE attribute_def SET meaning=$cgdi$The person or body that regularly receives cybersecurity information.$cgdi$, positive_example=$cgdi$The Audit Committee receives quarterly cybersecurity reports from the CISO.$cgdi$, negative_example=$cgdi$The Audit Committee oversees cybersecurity.$cgdi$ WHERE code='C1_routine_recipient';
UPDATE attribute_def SET meaning=$cgdi$The explicit cadence of routine cybersecurity reporting, such as monthly, quarterly, annually, or at each meeting.$cgdi$, positive_example=$cgdi$The CISO reports to the Audit Committee quarterly.$cgdi$, negative_example=$cgdi$The CISO reports significant incidents when they occur.$cgdi$ WHERE code='C1_routine_frequency';
UPDATE attribute_def SET meaning=$cgdi$The specific content of routine cybersecurity reports, such as threats, incidents, metrics, remediation, or program status.$cgdi$, positive_example=$cgdi$Quarterly reports cover threats, incidents, remediation status, and program metrics.$cgdi$, negative_example=$cgdi$The CISO provides cybersecurity updates.$cgdi$ WHERE code='C1_routine_content';
UPDATE attribute_def SET meaning=$cgdi$A cybersecurity event or condition that initiates escalation.$cgdi$, positive_example=$cgdi$A significant security incident triggers escalation to the Disclosure Committee.$cgdi$, negative_example=$cgdi$The CISO provides scheduled quarterly reports.$cgdi$ WHERE code='C1_event_trigger';
UPDATE attribute_def SET meaning=$cgdi$A severity, significance, materiality, potential-impact, or other threshold used to determine escalation.$cgdi$, positive_example=$cgdi$Incidents exceeding defined severity thresholds are escalated; potentially material incidents are sent to the Audit Committee.$cgdi$, negative_example=$cgdi$All incidents are handled by the security team.$cgdi$ WHERE code='C1_severity_materiality_threshold';
UPDATE attribute_def SET meaning=$cgdi$The governance route or sequence through which event information is escalated to management, committees, or the Board.$cgdi$, positive_example=$cgdi$The incident-response team escalates significant events to the Disclosure Committee and then, when potentially material, to the Audit Committee.$cgdi$, negative_example=$cgdi$The security team contains and remediates incidents.$cgdi$ WHERE code='C1_escalation_path';
